    /* Runtime matrix objects */
    MATRIX_ Grr_code = {0};
    MATRIX_ Grk_code = {0};
    MATRIX_ Gkr_code = {0};
    MATRIX_ Gkk_code = {0};
    MATRIX_ W_code = {0};
    MATRIX_ Gred_code = {0};
    MATRIX_ Ihisr_code = {0};
    MATRIX_ Ihisk_code = {0};
    MATRIX_ Ihisred_code = {0};
    MATRIX_ Vr_code = {0};
    MATRIX_ Vk_code = {0};
    MATRIX_ tmp_Grk_W_code = {0};
    MATRIX_ tmp_Grk_W_Gkr_code = {0};
    MATRIX_ tmp_Grk_W_Ihisk_code = {0};
    MATRIX_ tmp_W_Gkr_code = {0};
    MATRIX_ tmp_W_Gkr_Vr_code = {0};
    MATRIX_ tmp_W_Ihisk_code = {0};
    MATRIX_ tmp_Vk_sum_code = {0};
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double AN = 0.0;
    double AP = 0.0;
    double BN = 0.0;
    double BP = 0.0;
    double CN = 0.0;
    double CP = 0.0;
    double G11 = 0.0;
    double G12 = 0.0;
    double PN = 0.0;
    double PP = 0.0;
    double cr_C1_G_eff = 0.0;
    double cr_C1_G_eff_2 = 0.0;
    double cr_C1_G_eff_3 = 0.0;
    double cr_C1_G_eff_4 = 0.0;
    double cr_C3_G_eff = 0.0;
    double cr_C3_G_eff_2 = 0.0;
    double gNN = 0.0;
    double w1 = 0.0;
    /* User Ihis/history symbols */
    double G22 = 0.0;
    double Grc = 0.0;
    double Ihis_exclude_c3 = 0.0;
    double Ihis_exclude_c4 = 0.0;
    double cr_C1_Ihis_eff = 0.0;
    double cr_C1_Ihis_eff_2 = 0.0;
    double cr_C1_Ihis_eff_3 = 0.0;
    double cr_C1_Ihis_eff_4 = 0.0;
    double cr_C3_Ihis_eff = 0.0;
    double cr_C3_Ihis_eff_2 = 0.0;
    double cr_C3_Ihis_eff_3 = 0.0;
    double cr_G_7_7_eff = 0.0;
    double cr_G_8_8_eff = 0.0;
    double cr_G_9_9_eff = 0.0;
    double cr_Ihis_7_0_eff = 0.0;
    double cr_Ihis_8_0_eff = 0.0;
    double cr_Ihis_9_0_eff = 0.0;
    double w2 = 0.0;
    /* Block-matrix scalar aliases */
    double Gkk_k1_k1 = 0.0;
    double Gkk_k2_k2 = 0.0;
    double Gkk_k3_k3 = 0.0;
    double Gkk_shared_1 = 0.0;
    double Gkr_k1_N = 0.0;
    double Gkr_k1_P = 0.0;
    double Gkr_k2_N = 0.0;
    double Gkr_k2_P = 0.0;
    double Gkr_k3_N = 0.0;
    double Gkr_k3_P = 0.0;
    double Gkr_shared_1 = 0.0;
    double Gkr_shared_2 = 0.0;
    double Gkr_shared_3 = 0.0;
    double Gkr_shared_4 = 0.0;
    double Gkr_shared_5 = 0.0;
    double Grk_N_k1 = 0.0;
    double Grk_N_k2 = 0.0;
    double Grk_N_k3 = 0.0;
    double Grk_P_k1 = 0.0;
    double Grk_P_k2 = 0.0;
    double Grk_P_k3 = 0.0;
    double Grk_shared_1 = 0.0;
    double Grk_shared_2 = 0.0;
    double Grk_shared_3 = 0.0;
    double Grk_shared_4 = 0.0;
    double Grk_shared_5 = 0.0;
    double Grr_G_G = 0.0;
    double Grr_N_N = 0.0;
    double Grr_P_P = 0.0;
    double Grr_shared_1 = 0.0;
    double Grr_shared_2 = 0.0;
    double Grr_shared_3 = 0.0;
    double Grr_shared_4 = 0.0;
    double Grr_shared_5 = 0.0;

LOCAL_STATIC:
    /* User RAM-only G symbols */
    double gC = 0.0;

RAM_PASS1:
    /* Decode the optional global case selector into per-element local cases. */
    switch (case_id) {
    case 0: /* case 0: Trf_D/Y = Y/D; UCM_block = Block; YBox3 = Y; C1=case0, C2=case0, C3=case0 */
        C1_case_id = 0;
        C2_case_id = 0;
        C3_case_id = 0;
        break;
    case 1: /* case 1: Trf_D/Y = Y/D; UCM_block = Block; YBox3 = D; C1=case0, C2=case0, C3=case1 */
        C1_case_id = 0;
        C2_case_id = 0;
        C3_case_id = 1;
        break;
    case 2: /* case 2: Trf_D/Y = Y/D; UCM_block = Deblock; YBox3 = Y; C1=case0, C2=case1, C3=case0 */
        C1_case_id = 0;
        C2_case_id = 1;
        C3_case_id = 0;
        break;
    case 3: /* case 3: Trf_D/Y = Y/D; UCM_block = Deblock; YBox3 = D; C1=case0, C2=case1, C3=case1 */
        C1_case_id = 0;
        C2_case_id = 1;
        C3_case_id = 1;
        break;
    case 4: /* case 4: Trf_D/Y = D/Y; UCM_block = Block; YBox3 = Y; C1=case1, C2=case0, C3=case0 */
        C1_case_id = 1;
        C2_case_id = 0;
        C3_case_id = 0;
        break;
    case 5: /* case 5: Trf_D/Y = D/Y; UCM_block = Block; YBox3 = D; C1=case1, C2=case0, C3=case1 */
        C1_case_id = 1;
        C2_case_id = 0;
        C3_case_id = 1;
        break;
    case 6: /* case 6: Trf_D/Y = D/Y; UCM_block = Deblock; YBox3 = Y; C1=case1, C2=case1, C3=case0 */
        C1_case_id = 1;
        C2_case_id = 1;
        C3_case_id = 0;
        break;
    case 7: /* case 7: Trf_D/Y = D/Y; UCM_block = Deblock; YBox3 = D; C1=case1, C2=case1, C3=case1 */
        C1_case_id = 1;
        C2_case_id = 1;
        C3_case_id = 1;
        break;
    default:
        C1_case_id = 0;
        C2_case_id = 0;
        C3_case_id = 0;
        break;
    }
    /* Resolve RAM multi-case effective aliases as full values, never deltas. */
    switch (C3_case_id) {
    case 0:
        cr_C3_G_eff = Grc;
        cr_C3_G_eff_2 = Grc;
        break;
    case 1:
        cr_C3_G_eff = G_EPSILON;
        cr_C3_G_eff_2 = 0.0;
        break;
    default:
        cr_C3_G_eff = Grc;
        cr_C3_G_eff_2 = Grc;
        break;
    }
    /* Retained layout is selected during initialization. Runtime profile switching is not supported. */
    if (case_id == 0 || case_id == 2 || case_id == 4 || case_id == 6) {
        retained_profile = PROFILE_Y;
        nr_active = NR_Y;
    }
    else if (case_id == 1 || case_id == 3 || case_id == 5 || case_id == 7) {
        retained_profile = PROFILE_D;
        nr_active = NR_D;
    }
    int err = 0;
    /* ************************************************************************
