        }
    }
    g_mat_over[0][0] = gC;
    g_mat_over[0][1] = -gC;
    g_mat_over[1][0] = -gC;
    g_mat_over[1][1] = gC;
    setupGMatrix(2);

    err += matrixDim(&Grr_code, nr_active, nr_active);
    err += matrixDim(&Grk_code, nr_active, NK);
